async function searchUsers({ keyword, status, sort }) {
  const sql = `
    SELECT id, name, email, status
    FROM users
    WHERE name LIKE '%${keyword}%'
      AND status = '${status}'
    ORDER BY ${sort}
    LIMIT 100
  `;
  return db.$queryRawUnsafe(sql);
}

